  "亚运会、世博会带来客流高峰，疫情与灾害使出行减少；每个阶段都有本城目标与阶段总结。": "The Asian Games and World Expos bring ridership peaks, while epidemics and disasters reduce travel; every phase has city goals and a phase summary.",
  "自由建造可选起始年份并解锁全图；香港海洋公园与迪士尼乐园加入专属模型与客流。": "Free Build can start in a later year and unlock the whole map; Hong Kong's Ocean Park and Disneyland get their own models and visitor demand.",
  "更稳定的城市经营": "More stable city management",
