  "自由选址、绘制线路，为一座城市规划地铁。": "Choose station sites and draw metro lines for a city.",
  "经营挑战与自由建造两种模式。": "Challenge and Free Build modes.",
  "失败": "Failed",
  "游戏已暂停：先规划线路，再按": "Game paused. Plan your network, then press",
  "或": "or",
