  "高峰慢放：已关闭 · 开启后工作日早高峰（7–9 时）与晚高峰（17–19 时）自动按 1× 运行，高峰结束后恢复所选速度": "Slow Peaks: off · When on, weekday morning (07–09) and evening (17–19) peaks run at 1×, then the selected speed resumes",
  "已开启高峰慢放：工作日 7–9 时与 17–19 时自动按 1× 运行，便于观察高峰运营；高峰结束后恢复所选速度": "Slow Peaks on: weekday 07–09 and 17–19 run at 1× so you can watch peak operations; the selected speed resumes afterwards",
  "已关闭高峰慢放：全天按所选速度运行": "Slow Peaks off: the whole day runs at the selected speed",
  "停运时段快速掠过": "Fast-forward non-operating hours",
  "地铁停运的 00:00–06:00 按所选速度的 {n} 倍推进，一天更快过去；结算与客流不受影响": "While the metro is closed (00:00–06:00) the clock runs at {n}× the selected speed, so days pass faster. Accounting and ridership are unaffected.",
  "工作日早高峰（7–9 时）与晚高峰（17–19 时）自动按 1× 运行，高峰结束后恢复所选速度；也可点击顶栏的沙漏按钮（{key}）切换": "Weekday morning (07–09) and evening (17–19) peaks run at 1×, then the selected speed resumes. You can also use the hourglass button in the top bar ({key}).",
  "工作日早高峰（7–9 时）与晚高峰（17–19 时）自动按 1× 运行，高峰结束后恢复所选速度；也可点击顶栏的沙漏按钮切换": "Weekday morning (07–09) and evening (17–19) peaks run at 1×, then the selected speed resumes. You can also use the hourglass button in the top bar.",
  "1× / 3× / 8× / 24× 速度（24× 约 13 分钟一个游戏年）": "1× / 3× / 8× / 24× speed (24× is about 13 minutes per game year)",
  "高峰慢放：工作日早晚高峰自动按 1× 运行": "Slow Peaks: weekday peaks run at 1×",
  "推进 1 个月 / 3 个月 / 1 年": "Advance one month / three months / one year",
