  "把从「{a}」到分岔站的这一段改为一条独立线路，在分岔站与本线换乘": "Make the section from “{a}” to the junction an independent line, with an interchange at the junction",
  "转为独立线路": "Make independent line",
  "与其他线路贯通（把对方并入本线，保留本线名称与颜色）": "Through-run with another line (merge it into this line, keeping this line's name and color)",
