  "合并后为{topo}": "After merging: {topo}",
  "贯通": "Through-run",
  "请选择两条不同的线路": "Choose two different lines",
  "{a} 与 {b} 没有共同车站：先把其中一条线延长到另一条线的车站（通常是终点站），再贯通": "{a} and {b} share no station. Extend one line to a station of the other (usually a terminus) first, then through-run.",
  "合并后{line}「{reason}」，不能这样贯通": "After merging, {line} would be invalid (“{reason}”), so these lines cannot through-run this way",
  "只有带支线的线路可以拆出支线": "Only a line with branches can have a branch detached",
  "请选择支线的端点站": "Choose the terminus of the branch",
  "没有找到分岔站": "No junction station was found",
  "{a}—{b} 两线各有一段轨道，合并后保留 {l1} 的轨道，{l2} 的这段轨道拆除": "{a}–{b} has a track on each line; the merged line keeps the {l1} track and the {l2} track is removed",
  "支线已命名为「{name}」": "Branch named “{name}”",
  "已恢复按终点站显示支线方向": "Branch direction is shown by its terminus again",
  "已在草案中拆出 {line}（{a}—{b}），确认建设后生效；可在其详情中改名、改色": "{line} ({a}–{b}) detached in the draft. It takes effect after you confirm construction; rename or recolor it in its details.",
  "已在草案中把 {a} 并入 {b}（贯通运营，{topo}），确认建设后生效": "{a} merged into {b} in the draft (through-running, {topo}). It takes effect after you confirm construction.",
  "贯通与拆分只改变列车的运营组织，不改动轨道、不另收建设费，先进入建设草案，确认后生效。两线须有共同车站（通常是一条线的终点接到另一条线的终点）；相接处转向过急时，草案会提示调整线形。": "Through-running and splitting only change how trains are operated. Track is unchanged and there is no construction cost. Changes enter the draft and take effect after confirmation. The two lines must share a station (usually one line's terminus meets the other's); if the alignment turns too sharply there, the draft will ask you to adjust it.",
  "从 {a} 拆出 {b}（拆分线路，不另收建设费）": "{b} split from {a} (no construction cost)",
  "{a} 并入 {b}（贯通运营，不另收建设费）": "{a} merged into {b} (through-running, no construction cost)",
  "共线运营 {seg}（与 {line} 共线运营，沿用同一条轨道，不另收建设费）": "Shared track {seg} (runs with {line} on the same track, no construction cost)",
  "轨道 {seg} 改为{type}（与 {line} 共线运营，沿用同一条轨道，不另收建设费）": "Track {seg} changed to {type} (shared with {line}; charged once on the shared track)",
  "调整线形 {seg}（与 {line} 共线，随同一条轨道调整）": "Alignment adjusted: {seg} (shared with {line}, follows the same track)",
  "沿用 {line} 的既有轨道（共线运营），不另收建设费": "Uses the existing {line} track (shared running), no construction cost",
  "需要单独建轨道时，先 Shift+点击加一个转弯点": "For a separate track, Shift+click to add a bend first",
  "与 {line} 共线运营：沿用这两站之间的既有轨道，不另收建设费（需要单独建轨道时，先 Shift+点击加一个转弯点）": "Shared running with {line}: the existing track between these stations is reused at no construction cost (for a separate track, Shift+click to add a bend first)",
  "共线运营": "Shared track",
  "{n} 个区间": "{n} sections",
  "{a}—{b} · 与 {lines} 共用轨道": "{a}–{b} · shared with {lines}",
  "早高峰合计 {f} 列/时": "AM peak total {f} trains/h",
  "共线区段列车过密（上限 {n} 列/时）：客流大时可把其中一条线改走独立轨道（绘线时加转弯点）或升级车站加长编组。": "Too many trains on the shared section (limit {n} trains/h). With heavy demand, move one line onto its own track (add a bend when drawing) or upgrade stations for longer trains.",
  "m，需要较长坡道。让区间与两端站台采用相同的建设方式，或拉长两站距离；换乘站可以为本线单独设站台层（天地换乘）。": "m, requiring a longer ramp. Match the section and platform structure types, increase station spacing, or give this line its own platform level at an interchange (split-level interchange).",
  "天地换乘": "split-level interchange",
  "⇄ 天地换乘": "⇄ Split-level interchange",
  "主站台形式": "Main Platform Type",
  "各线路站台层（天地换乘）": "Platform level per line (split-level interchange)",
  "不同线路可在同一座车站分设地下、地面或高架站台，站内换乘；新增一层站台按该形式车站造价的 {n}% 计费，不同层之间换乘约多走 {m} 分钟。绘线接入建设方式不同的车站时会自动增设站台层。": "Lines can have underground, at-grade or elevated platforms in the same station with in-station transfers. An added platform level costs {n}% of a station of that type, and transfers between levels take about {m} minutes longer. Drawing a line into a station of a different type adds a platform level automatically.",
  "车站「{a}」增设{t}站台（天地换乘）": "Station “{a}”: {t} platform added (split-level interchange)",
  "增设{t}站台 {a}（天地换乘）": "Add {t} platform at {a} (split-level interchange)",
  "车站「{a}」以原有{t}站台为主站台": "Station “{a}”: the existing {t} platform becomes the main platform",
  "升级{t}站台 {a}": "Upgrade {t} platform at {a}",
  "车站「{a}」的{t}站台：{msg}": "Station “{a}”, {t} platform: {msg}",
  "把这条线路在本站的站台改为允许的建设方式，或移动车站。": "Change this line's platform here to a permitted type, or move the station.",
  "改为{t}站台": "Change to {t} platform",
  "把「{a}」本线站台改为{t}": "Change this line's platform at “{a}” to {t}",
  "「{a}」增设{t}站台，与{u}站台天地换乘": "“{a}”: {t} platform added, interchanging with the {u} platform",
  "线形": "Alignment",
  "平滑": "Smooth",
  "穿点": "Through points",
  "平滑曲线：Shift+点击放置的转弯点是控制柄，线路圆顺地从附近经过，放一个控制柄即可画出大半径弯道": "Smooth curve: bends placed with Shift+click act as control handles. The line sweeps past them, so one handle draws a wide, even curve.",
  "穿过转弯点：线路逐点经过每个转弯点（原画法），适合贴着道路或河岸走线": "Through bend points: the line passes through every bend (the original method), useful for following roads or riverbanks",
  "拖动车站或圆点调整线形 · 拖动菱形增加转弯点 · 双击删除转弯点 · 选中车站后拖动旋转手柄调整站台方向 · Ctrl+点击多选": "Drag stations or dots to reshape · drag diamonds to add bends · double-click to remove a bend · select a station and drag its rotate handle to turn the platform · Ctrl+click to multi-select",
  "旋转站台方向": "Rotate platform",
  "旋转 {line} 站台方向": "Rotate {line} platform",
  "拖动旋转（按 5° 吸附，按住 Shift 自由旋转）": "Drag to rotate (snaps to 5°; hold Shift to rotate freely)",
  "双击恢复自动方向": "Double-click to restore the automatic direction",
  "当前为自动方向：随相邻轨道取顺直方向": "Automatic: follows the smoothest direction of the adjoining track",
  "确认建设前都可以调整，进入草案": "Adjustable at any time before confirming; changes go into the draft",
  "已恢复自动站台方向（随相邻轨道取顺直方向）": "Automatic platform direction restored (follows the adjoining track)",
  "站台方向": "Platform direction",
  "已设定 · {b}": "Set · {b}",
  "自动 · {b}": "Automatic · {b}",
  "北偏东 {n}°": "N {n}° E",
