  "顺时针旋转 15°": "Rotate 15° clockwise",
  "恢复自动方向": "Restore automatic direction",
  "也可以在「修改」工具中选中车站，拖动旋转手柄（5° 吸附，Shift 自由旋转）。确认建设前随时可改；已建车站调整方向按线形调整规则计费。": "You can also select the station with the Modify tool and drag its rotate handle (snaps to 5°, Shift rotates freely). Change it any time before confirming; for built stations, alignment adjustment rules apply to the cost.",
  "平滑曲线": "Smooth curve",
  "穿过转弯点": "Through bend points",
  "线形（平滑曲线把转弯点当作控制柄；长度变化按线形调整规则计费）": "Alignment (a smooth curve treats bends as control handles; length changes follow the alignment adjustment rules)",
  "车站「{a}」调整站台方向": "Station “{a}”: platform direction adjusted",
