  "按问题查做法，边看边操作。": "Look up what to do and follow along on the map.",
  "按问题查做法，边看边操作。第一次玩可以先玩「新手教程 · 青湾」。": "Look up what to do and follow along on the map. New players can start with the Qingwan tutorial.",
  "第一次玩：四步修第一条线": "First game: your first line in four steps",
  "打开「人口密度」图层，找人最多的地方。": "Open the Population Density layer and find where most people live.",
  "用「绘线」（{tool.line}）从住宅区连到工作区，每隔约 1 km 放一个站。": "Use Draw Line ({tool.line}) to link homes to jobs, with a station about every 1 km.",
  "没有红色冲突后，点「确认建设」（{build.confirm}）。": "When there are no red conflicts, click Confirm ({build.confirm}).",
  "按 {pause} 开始，看车站客流，再继续扩线。": "Press {pause} to start, check station ridership, then keep extending.",
  "人口密度图层": "Population layer",
