  "怎么治堵": "How to ease congestion",
  "打开「道路拥堵」图层，找红色道路。": "Open the Road Congestion layer and find the red roads.",
  "打开「出行方向」图层，看车流往哪去。": "Open the Trip Directions layer to see where the traffic goes.",
  "沿这个方向修线并连到目的地，车站要在步行范围内。": "Build along that direction to the destination, with stations within walking distance.",
  "建完点顶栏「拥堵指数」看效果。": "After building, click Congestion in the top bar to see the effect.",
  "出行方向图层": "Trip directions layer",
  "怎么提高设施接驳比例": "How to raise a facility's metro access share",
  "在设施约 400 m 内建站，越近越好。": "Build a station within about 400 m of the facility; closer is better.",
  "让主要客源坐一条线直达，少换乘。": "Let the main visitors arrive on one line with few transfers.",
  "客流大就升级车站；票价别太高。": "Upgrade stations when busy, and keep fares moderate.",
  "设施详情里的「如何提高」会给出具体建议。": "How to Improve in the facility details gives specific advice.",
  "设施出行需求图层": "Facility demand layer",
  "怎么提高片区乘地铁占比": "How to raise a district's metro share",
  "在片区中心和人最多的地方设站。": "Place stations at the district centre and where most people live.",
  "看「出行方向」，把线修到居民要去的地方。": "Check Trip Directions and run the line to where residents go.",
  "少换乘、不拥挤、票价适中。": "Few transfers, no crowding, moderate fares.",
  "地铁覆盖图层": "Coverage layer",
  "车站或列车太挤": "Crowded stations or trains",
  "点开拥挤的车站，看「拥挤诊断」。": "Open the crowded station and read its Crowding Diagnosis.",
  "车站挤：升级车站规模。": "Crowded station: upgrade its size.",
  "列车挤：升级沿线车站加长列车，或修平行线分流。": "Crowded trains: upgrade stations along the line for longer trains, or build a parallel line.",
  "车站客流图层": "Station ridership layer",
  "票价怎么定": "How to set the fare",
  "点「资金」→「票价」，调好后点「应用新票价」。": "Click Funds → Fare, set it up, then click Apply New Fares.",
  "默认按里程计费：起步价含几公里，之后每段加价。": "Fares are distance-based by default: the base fare covers the first few km, then each section adds more.",
  "票价高收入多，但乘客少、满意度降。": "Higher fares earn more but lose riders and satisfaction.",
  "开局用默认票价，缺钱时小步上调加价或封顶。": "Start with the default fares; when money is short, raise the per-section charge or cap in small steps.",
  "票价设置": "Fare settings",
  "钱不够怎么办": "Short of money?",
  "满意度高、完成任务，拨款就多。": "High satisfaction and completed tasks bring bigger grants.",
  "先修客流大的短线，车站先用中型。": "Build short, busy lines first, with medium stations.",
  "急需时可以发债，注意按期还款。": "Issue bonds if you must, and repay on time.",
  "换乘、贯通、共线与平滑曲线": "Interchanges, through-running, shared track and curves",
  "换乘：绘线时点击已有车站。": "Interchange: click an existing station while drawing.",
  "天地换乘：高架线接入地下站会自动加站台层。": "Split-level: an elevated line joining an underground station adds a platform level automatically.",
  "贯通、拆开：右键线路，选「贯通、拆开与支线」。": "Through-run or split: right-click a line and choose Through-running, splitting and branches.",
  "共线：连接已有轨道的两站、不加转弯点，就免费沿用。": "Shared track: connect two stations already joined by track, with no bend, to reuse it for free.",
  "平滑曲线：工具条「线形」选「平滑」，Shift+点击放控制柄。": "Smooth curves: choose Smooth under Alignment and Shift+click to place handles.",
  "改名、改色：右键车站或线路，或点详情标题。": "Rename or recolor: right-click a station or line, or click the details title.",
  "时间太慢，或想看高峰": "Time too slow, or watching the peaks",
  "最快 24×，约 13 分钟一年；也可以点 +1 月、+3 月、+1 年。": "Up to 24×, about 13 minutes a year; or use +1 Month, +3 Months, +1 Year.",
  "打开沙漏「高峰慢放」（{time.peakSlow}），高峰自动放慢到 1×。": "Turn on the hourglass Slow Peaks ({time.peakSlow}) and peaks slow to 1× automatically.",
