  "2005 年 9 月香港迪士尼乐园开幕（史实）；同年 8 月迪士尼线通车（史实）": "Hong Kong Disneyland opened in September 2005 (historical); the Disneyland Resort line opened that August (historical)",
  "1977 年 1 月海洋公园开幕（史实）；南朗山一侧的山上园区属郊野山地": "Ocean Park opened in January 1977 (historical); the headland section on Nam Long Shan is country-park hillside",
  "主题乐园：周末与假日客流明显高于工作日（估算）。": "Theme park: visits on weekends and holidays are much higher than on weekdays (estimate).",
  "主题乐园：周末与假日客流明显高于工作日（估算）；位于大屿山竹篙湾。": "Theme park: visits on weekends and holidays are much higher than on weekdays (estimate); located at Penny's Bay, Lantau.",
  "香港国际机场启用，启德机场关闭": "Hong Kong International Airport opens; Kai Tak closes",
  "港岛南区黄竹坑与南朗山上的海洋主题公园开幕，成为周末与假日的大型休闲目的地。": "The marine theme park at Wong Chuk Hang and Nam Long Shan opens, a major weekend and holiday destination on the south side of Hong Kong Island.",
  "史实背景：地下铁路首段通车": "Historical background: first MTR section opens",
  "现实中观塘线首段（观塘至石硖尾）于 1979 年 10 月通车；游戏不会替玩家建设对应线路。": "In reality the first section of the Kwun Tong line (Kwun Tong to Shek Kip Mei) opened in October 1979; the game does not build it for you.",
  "青马大桥通车": "Tsing Ma Bridge opens",
  "青衣与马湾之间的机场核心计划干道，大屿山与市区的公路联系形成。": "The Airport Core Programme road between Tsing Yi and Ma Wan links Lantau with the urban area.",
  "香港迪士尼乐园开幕": "Hong Kong Disneyland opens",
