  "往期阶段总结": "Past phase summaries",
  "片区倾向只改变增长的去向，人口与岗位总量仍按人口曲线；地铁让车站周边更受欢迎，但对总量的带动有上限。": "District trends only change where growth goes; total population and jobs still follow the population curve. The metro makes station areas more attractive, but its boost to the totals is capped.",
  "模拟影响：": "Simulated effect: ",
  "此后": "over the next",
  "年内": "years",
  "个月内": "months",
  "人口与岗位增长加快": "population and jobs grow faster",
  "人口与岗位增长放缓": "population and job growth slows",
  "人口增长加快": "population grows faster",
  "岗位增长加快": "jobs grow faster",
